# Generated by `cargo xtask formula` in michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.15.0/acs-0.15.0-aarch64-apple-darwin.tar.gz"
      sha256 "4e3065831b237e1e4a1599e1851a8b3f4f352a78e5eb63cd65a23983ee38a012"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.15.0/acs-0.15.0-x86_64-apple-darwin.tar.gz"
      sha256 "b56a59058e024d6a7ea67ed9d2207bd5c7702b17585425cc0b525a0c840cec62"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.15.0/acs-0.15.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "068f51af7b9cbc335b4d091251e55542a9f6112c398b23d618864e83257b001b"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.15.0/acs-0.15.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "35f7c9b3b37d98551e741ab9f0bf0107717c93c5b49ab4fd47528b668fe31860"
    end
  end

  def install
    bin.install "acs"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
  end
end
